DROP TABLE IF EXISTS `best_selling_products`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `best_selling_products`  AS SELECT `p`.`product_name` AS `product_name`, sum(`oi`.`qty`) AS `total_sold`, sum(`oi`.`qty` * `p`.`price`) AS `total_revenue` FROM (`ordered_items` `oi` join `products` `p` on(`oi`.`PID` = `p`.`PID`)) GROUP BY `p`.`PID` ORDER BY sum(`oi`.`qty`) DESC LIMIT 0, 10 ;

