--
-- Structure for view `employee_details`
--
DROP TABLE IF EXISTS `employee_details`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `employee_details`  AS SELECT `e`.`EID` AS `EID`, concat(`e`.`fn`,' ',`e`.`mid`,' ',`e`.`ln`) AS `fullname`, `e`.`age` AS `age`, `e`.`gender` AS `gender`, `e`.`email` AS `email`, `e`.`phone_num` AS `phone_num`, `e`.`bday` AS `bday`, `e`.`profile` AS `profile`, `r`.`rolename` AS `roleName`, `u`.`username` AS `username`, `u`.`password` AS `password`, `a`.`street` AS `street`, `a`.`city` AS `city`, `a`.`province` AS `province`, `a`.`zipcode` AS `zipcode`, date_format(`e`.`date_hired`,'%M %e, %Y, %l:%i %p') AS `date_hired` FROM (((`employees` `e` join `users` `u` on(`e`.`UID` = `u`.`UID`)) join `roles` `r` on(`e`.`RID` = `r`.`RID`)) join `address` `a` on(`a`.`EID` = `e`.`EID`)) WHERE `e`.`RID` = `r`.`RID` AND `e`.`UID` = `u`.`UID` AND `e`.`EID` = `a`.`EID` ;

